(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin((x+w1x)*0.035+t*0.5)*8+Math.cos((y+w1y)*0.025-t*0.4)*6;
  const w2y = Math.cos((y+w1y)*0.03-t*0.45)*8+Math.sin((x+w1x)*0.028+t*0.55)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9]
  ];
  const src2 = [
    [200+Math.sin(t*1.2+1)*60,100+Math.cos(t*0.9)*40,0.15,3.0],
    [280+Math.cos(t*1.1)*50,140+Math.sin(t*1.3)*35,0.18,2.8],
    [160+Math.sin(t*0.8+3)*70,160+Math.cos(t*1.0+2)*45,0.13,3.2]
  ];
  let aS=0,iS=0,aS2=0,iS2=0;
  for(const[sX,sY,f,sp]of src){const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);aS+=Math.sin(d*f-t*sp);iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);}
  for(const[sX,sY,f,sp]of src2){const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);aS2+=Math.sin(d*f-t*sp);iS2+=Math.sin(d*f*0.6+t*sp*0.5+2.0);}
  const act=aS/6,inh=iS/6,act2=aS2/3,inh2=iS2/3;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2+Math.sin(sx*0.07+t*1.8)*Math.cos(sy*0.06-t*1.5)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4+Math.sin(dist*0.03-ang*2-t*0.8)*0.2;
  const r1=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const r2=Math.tanh((act2-inh2*0.6+r1*0.4+bg*0.2)*2.5);
  const reaction=Math.tanh(r1*0.6+r2*0.4+Math.sin(r1*r2*3)*0.2);
  const cellBase=Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5;
  const cellWave=Math.sin(sx*0.22-t*1.5)*Math.cos(sy*0.19+t*1.2)*0.3;
  const cell=Math.tanh((cellBase+cellWave)*1.5)*0.3;
  const fine=Math.sin(sx*0.3+t*3)*Math.sin(sy*0.3-t*2.5)*0.08;
  const pulse=0.5+Math.sin(t*0.4)*0.1;
  const blend=reaction*0.6*cell*0.2+fine+r2*0.15+pulse*0.05;
  const v=Math.tanh(blend*1.8)*0.5+0.5;
  const pal=[[5,10,45],[12,45,85],[18,90,120],[25,140,130],[80,175,110],[180,195,75],[220,170,55],[215,120,65],[190,75,75],[140,45,80],[80,25,65],[30,15,55],[5,10,45]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const sf=f*f*(3-2*f);
  const lum=0.8+Math.sin(reaction*Math.PI)*0.2;
  const edge=Math.abs(reaction)>0.7?1.15:Math.abs(reaction)>0.4?1.05:1.0;
  const glow=Math.max(0,1-Math.abs(reaction))*0.15;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge+glow*30)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge+glow*50)|0)
  ];
}
